+// Package modal adapts the official Modal Go client for sandbox-kit injection.
+package modal
+
+import (
+	sdk "github.com/modal-labs/modal-client/go"
+	sandbox "github.com/sandbox-kit/kit"
+)
+
+// Config preserves Modal's native initialization options, including token-pair
+// and OAuth authentication, environment selection, and transport hooks.
+type Config = sdk.ClientParams
+
+// Adapter retains the original Modal client. The caller owns its lifetime and
+// closes it through SDK().Close(); sandbox-kit never closes it implicitly.
+type Adapter struct {
+	client *sdk.Client
+}
+
+var _ sandbox.SandboxAdapter = (*Adapter)(nil)
+
+// NewAdapter initializes Modal with its native configuration resolution.
+// Nil uses Modal environment variables and its profile file. Authentication is
+// not verified here: Modal may defer credential errors until the first request.
+// Constructor errors are returned exactly as supplied by the SDK.
+func NewAdapter(config *Config) (*Adapter, error) {
+	client, err := sdk.NewClientWithOptions(config)
+	if err != nil {
+		return nil, err
+	}
+	return NewAdapterWithClient(client)
+}
+
+// NewAdapterWithClient injects an already initialized client without changing
+// configuration or making requests. The caller retains ownership of the client.
+func NewAdapterWithClient(client *sdk.Client) (*Adapter, error) {
+	if client == nil {
+		return nil, sdk.InvalidError{Exception: "sandbox-kit: Modal client is nil"}
+	}
+	return &Adapter{client: client}, nil
+}
+
+// SandboxProvider identifies this adapter for internal client configuration.
+func (*Adapter) SandboxProvider() string { return "modal" }
+
+// SDK returns the original SDK client, preserving provider-native services,
+// request options, results, errors, and cleanup behavior.
+func (a *Adapter) SDK() *sdk.Client { return a.client }
